//! Stats JSON helpers (/stats, cluster workers) and the embedded console table. Served by api.rs.

use crate::head::{now, Shared, Worker};
use crate::proto::KIND_SHA;

/// The old single-file dashboard, served at /legacy and as the fallback when no console is embedded.
pub const LEGACY: &str = include_str!("dash.html");

mod ui {
    // (path, content type, bytes) of the embedded console; generated by build.rs from console/build.
    include!(concat!(env!("OUT_DIR"), "/ui_files.rs"));
}

/// The console file for a request path: an exact file, else index.html (SPA routes), else None (not built).
pub fn ui_file(path: &str) -> Option<&'static (&'static str, &'static str, &'static [u8])> {
    ui::FILES.iter().find(|f| f.0 == path).or_else(|| ui::FILES.iter().find(|f| f.0 == "/index.html"))
}

pub fn worker_json(id: u64, w: &Worker) -> serde_json::Value {
    let h = w.hello.as_ref();
    serde_json::json!({
        "id": id, "addr": w.addr, "threads": w.threads, "chunks": w.chunks, "numbers": w.numbers,
        "secs": (w.secs * 1e6).round() / 1e6, "rate": w.rate.round(), "busy": !w.inflight.is_empty(),
        "cpu": (w.cpu * 10.0).round() / 10.0, "mem_used": w.mem_used, "mem_total": w.mem_total,
        "version": w.version, "node_id": h.map(|h| &h.node_id), "host": h.map(|h| &h.host),
        "jobs_inflight": w.inflight.iter().map(|t| t.0).collect::<Vec<u64>>(),
        "virtual": h.is_some_and(|h| h.virtual_node), "inv": h.map(|h| &h.inv),
        "presence": if w.presence.is_empty() { "idle" } else { w.presence.as_str() }, "blocked": w.blocked, "cap": w.cap, "energy_j": w.energy_j,
    })
}

pub fn stats(sh: &Shared, detail: bool) -> String {
    let st = sh.0.lock().unwrap();
    let job = st.job.as_ref().map_or("null".into(), |j| {
        let kind = if j.kind == KIND_SHA { "sha256" } else { "cmd" };
        format!(r#"{{"id":{},"kind":"{kind}","done":{},"total":{},"secs":{:.3}}}"#, j.id, j.total - j.left, j.total, j.started.elapsed().as_secs_f64())
    });
    let last = st.last.as_ref().map_or("null".into(), |m| format!("\"{m}\""));
    let ws: Vec<String> = st.workers.iter().map(|(id, w)| worker_json(*id, w).to_string()).collect();
    // Task stream data only when the dashboard's Details toggle is on.
    let events = if detail {
        let ev: Vec<String> = st.events.iter().map(|(w, a, b)| format!("[{w},{a:.3},{b:.3}]")).collect();
        format!(r#","events":[{}]"#, ev.join(","))
    } else {
        String::new()
    };
    format!(r#"{{"now":{:.3},"job":{job},"last":{last},"workers":[{}]{events}}}"#, now(), ws.join(","))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::proto::{Hello, Inventory};

    #[test]
    fn stats_reports_hello() {
        let sh: Shared = Default::default();
        let hello = Hello { node_id: "n1/v2".into(), host: "lab-07".into(), virtual_node: true, inv: Inventory { cores_logical: 8, ..Default::default() }, join_code: None };
        sh.0.lock().unwrap().workers.insert(1, Worker { addr: "10.0.0.7".into(), version: 2, hello: Some(hello), ..Default::default() });
        sh.0.lock().unwrap().workers.insert(2, Worker { addr: "10.0.0.8".into(), version: 1, ..Default::default() }); // v1: no hello
        let v: serde_json::Value = serde_json::from_str(&stats(&sh, false)).unwrap();
        let ws = v["workers"].as_array().unwrap();
        let w = ws.iter().find(|w| w["id"] == 1).unwrap();
        assert_eq!((w["node_id"].as_str(), w["host"].as_str(), w["virtual"].as_bool(), w["version"].as_u64()), (Some("n1/v2"), Some("lab-07"), Some(true), Some(2)));
        assert_eq!(w["inv"]["cores_logical"], 8);
        assert!(ws.iter().find(|w| w["id"] == 2).unwrap()["node_id"].is_null());
    }
}
